@triton.jit
def reduction_backward_kernel(dy_ptr, dx_ptr, n_elements, BLOCK: tl.constexpr):
    offsets = tl.arange(0, BLOCK)
    mask = offsets < n_elements
    dy = tl.load(dy_ptr)
    tl.store(dx_ptr + offsets, dy, mask=mask)

